import json,sys
raw=open('$F').read()
# file may contain the JSON result directly or wrapped; find first '{'
start=raw.find('{')
data=json.loads(raw[start:]) if start>=0 else {}
def walk(d,p=''):
    if isinstance(d,dict):
        for k,v in d.items():
            print(p+k, type(v).__name__, (len(v) if isinstance(v,(str,list,dict)) else v))
            if isinstance(v,dict) and len(p)<20: walk(v,p+k+'.')
walk(data)
"

