export const meta = {
  name: 'implement-routed',
  description: 'implement.js com roteamento de modelo por papel (Opus 5 executa specs claras; Fable 5 julga/gerencia: setup, retry, verify-plan, PR) e verify adaptado ao gate dotnet do MonoDreams',
  whenToUse: 'Invocado pela skill /implement (variante roteada) com um plano APROVADO. Não invocar sem plano com Contract block.',
  phases: [
    { title: 'Setup', detail: 'valida branch, semeia/retoma ledger, divide o plano em ondas, commita contrato deep-plan se houver', model: 'fable' },
    { title: 'Implement', detail: 'uma onda por vez: agente fresco (Opus) implementa, verify incremental, commit, push, ledger; retry julgado por Fable', model: 'opus' },
    { title: 'Verify', detail: 'gate dotnet com fix loop (≤3, Opus) + reconciliação verify-plan (Fable) + 1 rodada de fix (Opus)' },
    { title: 'PR', detail: 'rebase sobre origin/main, push, gh pr create com corpo extenso em INGLÊS (Fable)', model: 'fable' },
  ],
}

// args chega como string JSON-encoded em alguns runtimes — shim defensivo.
const ARGS = (() => {
  try { return typeof args === 'string' ? JSON.parse(args) : (args ?? {}) } catch (e) { return {} }
})()

const REQUIRED = ['planPath', 'branch', 'repoRoot', 'ledgerPath', 'timestamp']
const missingArgs = REQUIRED.filter((k) => !ARGS[k])
if (missingArgs.length) {
  return { status: 'blocked', stage: 'args', reason: `args obrigatórios ausentes: ${missingArgs.join(', ')}` }
}

const BASE = ARGS.baseBranch || 'main'
const MAX_WAVES = Math.min(ARGS.maxWaves || 8, 12)
const ROLE_DIR = '/Users/rodrigooliveira/.claude/skills/implement/agents'

// Roteamento de modelo por papel (diretiva do usuário, 2026-08-19):
//  - Opus 5 quando a especificação é clara (executores: waves, verify, recon-fix).
//  - Fable 5 quando há ambiguidade, ou o agente JULGA/AVALIA trabalho de Opus, ou é advisor/manager
//    (setup = fatia o plano; wave-retry = diagnostica a falha de um Opus; verify-plan = audita as ondas;
//     pr-author = sintetiza decisões e residuais).
// ARGS.models = {setup, wave, waveRetry, verify, recon, reconFix, pr} sobrepõe por papel; ARGS.model sobrepõe TODOS.
const MODELS = {
  setup: 'fable',
  wave: 'opus',
  waveRetry: 'fable',
  verify: 'opus',
  recon: 'fable',
  reconFix: 'opus',
  pr: 'fable',
  ...(ARGS.models || {}),
}
if (ARGS.model) for (const k of Object.keys(MODELS)) MODELS[k] = ARGS.model

// ---------------------------------------------------------------------------
// Schemas
// ---------------------------------------------------------------------------

const DECISION = {
  type: 'object',
  required: ['point', 'chosen', 'why'],
  properties: {
    point: { type: 'string', maxLength: 240 },
    options: { type: 'array', items: { type: 'string', maxLength: 160 }, maxItems: 4 },
    chosen: { type: 'string', maxLength: 240 },
    why: { type: 'string', maxLength: 240 },
  },
}

const SETUP_RESULT = {
  type: 'object',
  required: ['branchOk', 'resumed', 'waves'],
  properties: {
    branchOk: { type: 'boolean' },
    resumed: { type: 'boolean', description: 'true se um ledger pré-existente com ondas concluídas foi encontrado' },
    waves: {
      type: 'array',
      maxItems: 12,
      description: 'APENAS ondas pendentes (numa retomada, exclua as já concluídas no ledger)',
      items: {
        type: 'object',
        required: ['id', 'title', 'goal'],
        properties: {
          id: { type: 'integer' },
          title: { type: 'string', maxLength: 80 },
          goal: { type: 'string', maxLength: 400 },
          contractItems: { type: 'array', items: { type: 'string', maxLength: 200 }, maxItems: 15 },
          files: { type: 'array', items: { type: 'string', maxLength: 200 }, maxItems: 20 },
        },
      },
    },
    planSummary: { type: 'string', maxLength: 600 },
    prTitle: { type: 'string', maxLength: 100, description: 'Conventional Commits, em INGLÊS (repo convention)' },
    contractCommitted: { type: 'boolean', description: 'true se um contrato deep-plan foi commitado em .claude/deep-plan/' },
    blockedReason: { type: 'string', maxLength: 400 },
  },
}

const WAVE_RESULT = {
  type: 'object',
  required: ['status', 'untestedItems'],
  properties: {
    status: { type: 'string', enum: ['done', 'blocked'] },
    commitShas: { type: 'array', items: { type: 'string', maxLength: 40 }, maxItems: 10 },
    decisions: { type: 'array', items: DECISION, maxItems: 10 },
    testEvidence: {
      type: 'array',
      maxItems: 15,
      description: 'teste(s) nomeado(s) por contract item da onda, ou justificativa na',
      items: { type: 'object', required: ['item'], properties: { item: { type: 'string', maxLength: 200 }, tests: { type: 'array', items: { type: 'string', maxLength: 160 }, maxItems: 5 }, na: { type: 'string', maxLength: 200 } } },
    },
    untestedItems: { type: 'array', items: { type: 'string', maxLength: 240 }, maxItems: 15, description: 'itens sem teste e sem justificativa — gate: deve ser vazio para fechar a onda' },
    handoff: { type: 'string', maxLength: 300 },
    blockedReason: { type: 'string', maxLength: 500 },
  },
}

const VERIFY_RESULT = {
  type: 'object',
  required: ['green'],
  properties: {
    green: { type: 'boolean' },
    commits: { type: 'array', items: { type: 'string', maxLength: 40 }, maxItems: 10 },
    failingSummary: { type: 'string', maxLength: 1500, description: 'testes/etapas ainda falhando, telegráfico' },
  },
}

const RECON_RESULT = {
  type: 'object',
  required: ['missing', 'diverged', 'unplanned', 'untestedPremises'],
  properties: {
    missing: { type: 'array', maxItems: 20, items: { type: 'object', required: ['item'], properties: { item: { type: 'string', maxLength: 240 }, note: { type: 'string', maxLength: 240 } } } },
    diverged: { type: 'array', maxItems: 20, items: { type: 'object', required: ['item'], properties: { item: { type: 'string', maxLength: 240 }, planned: { type: 'string', maxLength: 200 }, actual: { type: 'string', maxLength: 200 }, file: { type: 'string', maxLength: 160 } } } },
    unplanned: { type: 'array', maxItems: 20, items: { type: 'object', required: ['file'], properties: { file: { type: 'string', maxLength: 160 }, note: { type: 'string', maxLength: 240 } } } },
    untestedPremises: { type: 'array', maxItems: 15, items: { type: 'object', required: ['premise', 'file'], properties: { premise: { type: 'string', maxLength: 200 }, file: { type: 'string', maxLength: 160 } } } },
  },
}

const PR_RESULT = {
  type: 'object',
  required: ['status'],
  properties: {
    status: { type: 'string', enum: ['pr-opened', 'blocked', 'blocked-gate'] },
    prNumber: { type: 'integer' },
    prUrl: { type: 'string', maxLength: 200 },
    rebased: { type: 'boolean', description: 'true se o rebase trouxe commits novos de main' },
    blockedReason: { type: 'string', maxLength: 600 },
  },
}

// ---------------------------------------------------------------------------
// Prompt helpers
// ---------------------------------------------------------------------------

// O gate deste repo (docs/agents/skills-config.md › Verify). Ordem OBRIGATÓRIA: core antes de tudo
// (o content step MGCB resolve MonoDreams.dll por caminho absoluto — sem o core buildado, falha com
// "Failed to create importer 'YarnSpinnerImporter'"). A sln é minúscula: monodreams.sln.
const VERIFY_CMDS = [
  `dotnet build ${ARGS.repoRoot}/MonoDreams/MonoDreams.csproj --configuration Release`,
  `dotnet test ${ARGS.repoRoot}/monodreams.sln --configuration Release -m:1 -p:RestoreDisableParallel=true`,
  `MONODREAMS_TEST_SEED=8 dotnet test ${ARGS.repoRoot}/MonoDreams.Tests/MonoDreams.Tests.csproj --configuration Release --no-build -m:1 -p:RestoreDisableParallel=true`,
].join('\n')

function ctx() {
  return [
    `Repo: ${ARGS.repoRoot} (trabalhe SOMENTE dentro dele; use rg, nunca grep -r; não leia /tmp, ~, nem worktrees irmãs).`,
    `Branch de trabalho: ${ARGS.branch} (base: origin/${BASE}). Guarda obrigatória: git branch --show-current deve retornar exatamente isso; se divergir, retorne blocked imediatamente.`,
    `Push autorizado SOMENTE em "git push origin ${ARGS.branch}". Nunca force (exceto --force-with-lease pós-rebase, apenas o PR author), nunca ${BASE}.`,
    `Plano aprovado: ${ARGS.planPath}. Ledger: ${ARGS.ledgerPath} (fora do repo — NUNCA commitá-lo).`,
    `IDIOMA de commits, PR e código-comentário: INGLÊS (docs/agents/skills-config.md › Conventions) — isso SOBREPÕE qualquer role file que diga pt-br. Conventional Commits type(scope): description.`,
    `Regra do repo (CLAUDE.md › Workflow): antes de implementar em um módulo, leia docs/CORE_TENETS.md e MonoDreams/<módulo>/docs/premises.md dos módulos tocados. Nunca stage .worktrees/. Antes de todo commit: git grep -l '<<<<<<< HEAD' -- '*.cs' '*.md' '*.json'.`,
    `Seu texto final é parseado como dado estruturado pelo orquestrador — siga o schema, sem prosa extra.`,
  ].join('\n')
}

function setupPrompt() {
  return `${ctx()}

Você é o agente de SETUP do workflow /implement (variante roteada).

1. Confirme a guarda de branch e que a working tree está limpa (git status --porcelain; untracked .worktrees/ é tolerado e NUNCA staged).
2. Leia o plano (${ARGS.planPath}) por inteiro — prosa + "## Contract" (+ §3b Resoluções, matriz/precondition diff se houver).
3. Ledger: se ${ARGS.ledgerPath} já existe, leia-o e PRESERVE todo o conteúdo existente — em especial a seção "## Diretivas (do usuário)", que é canal de injeção do orquestrador/usuário e tem precedência sobre decisões autônomas dos agentes. É RETOMADA (resumed=true) somente se houver ondas marcadas como concluídas com commits; um ledger semeado só com cabeçalho/diretivas NÃO é retomada. Se não existir, crie-o (crie o diretório se preciso) com:
   - plano: ${ARGS.planPath} | branch: ${ARGS.branch} | iniciado: ${ARGS.timestamp}
   - seções "## Diretivas (do usuário)" (vazia se nenhuma), "## Ondas" (checklist), "## Decisões", "## Handoffs".
4. ${ARGS.deepPlanContractPath ? `Contrato deep-plan: ${ARGS.deepPlanContractPath}. Se ainda não estiver commitado na branch sob .claude/deep-plan/, copie-o para lá (nome <branch-com-/-vira-->-<shortSha>.md), git add + commit ("chore(plan): add deep-plan contract") + push. É o artefato que o gate de PR em domínio sensível lê.` : 'Sem contrato deep-plan para commitar.'}
5. Divida o ESCOPO DESTA RUN (as Diretivas do ledger delimitam qual fatia do plano esta run cobre — respeite-as; itens do Contract fora do escopo desta run NÃO viram onda) em ATÉ ${MAX_WAVES} ondas PENDENTES, em ordem de dependência. Cada onda: id, title, goal (o que estará verdadeiro ao final), contractItems (números/textos do Contract que ela cobre — todo item do Contract EM ESCOPO deve pertencer a exatamente uma onda), files (palpite inicial). Ondas pequenas o bastante para um agente fresco concluir sem estourar contexto (~≤8 arquivos novos/alterados por onda como régua).
6. Registre a divisão de ondas no ledger.

Se algo impedir (branch errada, plano sem Contract, tree suja), retorne branchOk=false/blockedReason. Sugira também o prTitle (Conventional Commits, INGLÊS)${ARGS.prTitleHint ? ` — hint do usuário: "${ARGS.prTitleHint}"` : ''}.`
}

function wavePrompt(wave, retryReason) {
  return `${ctx()}

Leia ${ROLE_DIR}/wave-implementer.md e opere como esse agente (lembrete: commits/PR em INGLÊS; verify incremental deste repo = dotnet build core + dotnet test MonoDreams.Tests/ direcionado; gate completo fica para a fase Verify).

Sua onda:
${JSON.stringify(wave, null, 2)}
${retryReason ? `\nRETRY (você é o agente-julgador desta retomada): a tentativa anterior desta onda falhou com: "${retryReason}". Antes de continuar, AVALIE o que o agente anterior produziu — leia o ledger, o git log/diff da branch e o estado da working tree — e decida o que aproveitar, corrigir ou refazer. Pode haver trabalho não commitado ou parcialmente commitado. Registre em decisions o veredito sobre o trabalho anterior.` : ''}`
}

function verifyPrompt(attempt, previousFailing) {
  return `${ctx()}

Você é o agente de VERIFY (tentativa ${attempt} de 3) do workflow /implement. Todas as ondas commitaram; seu trabalho é deixar o gate inteiro verde.

Execute o gate configurado deste repo (docs/agents/skills-config.md › Verify), NA ORDEM (core primeiro — regra MGCB):
${VERIFY_CMDS}
(Redirecione saídas longas para um arquivo temporário e leia as falhas de lá se a saída estourar.)
${previousFailing ? `Falhas pendentes da tentativa anterior: ${previousFailing}` : ''}

Se a mudança desta branch tocar platform/rendering/content paths, rode TAMBÉM o web head: dotnet build ${ARGS.repoRoot}/MonoDreams.Examples.Web/MonoDreams.Examples.Web.csproj -p:MonoDreamsPlatform=web (workload wasm-tools está instalado). Se tocar MonoDreams/<module>/ ou o CLI, rode o manifest-honesty do(s) módulo(s) tocado(s): MONODREAMS_MANIFEST_HONESTY=1 MONODREAMS_HONESTY_MODULE=<name> dotnet test ${ARGS.repoRoot}/MonoDreams.Cli.Tests/ --filter FullyQualifiedName~ManifestHonesty.

Conserte as falhas que encontrar (mudanças cirúrgicas; siga CLAUDE.md e as premises dos módulos tocados), commit ("fix: post-implementation verify fixes" ou mais específico, EM INGLÊS) + push a cada grupo de fixes. Teste falhando de forma suspeita: confirme com re-run isolado (--filter) antes de tratar como regressão — a suíte tem ordem determinística (DeterministicCollectionOrderer), então falha real é reproduzível.

green=true SOMENTE com os comandos do gate acima passando por inteiro. Se não conseguir, green=false + failingSummary preciso.`
}

function reconPrompt(isRecheck) {
  return `${ctx()}

Você é o agente de VERIFY-PLAN${isRecheck ? ' (RE-CHECK pós-fix)' : ''} — reconciliação plano↔diff com olhos frescos. Você NÃO implementou nada; não assuma intenções. Seu papel é AUDITAR o trabalho dos agentes implementadores contra o contrato.

Leia ${ARGS.repoRoot}/.claude/skills/verify-plan/SKILL.md e aplique a Phase 1 (coverage / fidelity / scope-creep), com:
- Plano: ${ARGS.planPath} (use o "## Contract" refutado + as resoluções §3b, que PREVALECEM; considere apenas os itens EM ESCOPO desta run, per Diretivas do ledger ${ARGS.ledgerPath}).
- Diff: git fetch origin ${BASE} && git diff origin/${BASE}...HEAD (tudo já está commitado).

Bounded: NÃO é bug hunt. Item a item do contrato.

4º bucket MECÂNICO — untestedPremises: rode git diff origin/${BASE}...HEAD -- '**/docs/premises.md' e liste toda premissa adicionada/alterada nesta branch cujo campo **Tests:** está "none yet" ou ausente. Para premissa introduzida no PR isso é gate de merge (CLAUDE.md › Premises: premissa nova exige teste no mesmo PR), não sugestão.

Retorne os quatro buckets estruturados; vazios se limpos.`
}

function reconFixPrompt(recon) {
  return `${ctx()}

Leia ${ROLE_DIR}/wave-implementer.md e opere como esse agente, com uma diferença: sua "onda" são os achados do verify-plan abaixo. Resolva cada Missing (implemente o item contratado) e cada Diverged (alinhe o código ao contrato — se o desvio for deliberado e superior, mantenha o código e registre como decisão com o porquê). Unplanned: avalie; remova se for scope-creep sem valor, registre como decisão se ficar. UntestedPremises: escreva o teste que protege cada premissa (um teste que QUEBRA se a premissa for violada, não happy path — modelo: os testes citados nas premises da foundation) e preencha o campo **Tests:** dela. Verify incremental + commit + push (EM INGLÊS) + ledger como de costume.

Achados:
${JSON.stringify(recon, null, 2)}`
}

function prPrompt(setup, decisions, residual, mustFullBuild, testEvidence) {
  return `${ctx()}

Leia ${ROLE_DIR}/pr-author.md e opere como esse agente (OVERRIDE de idioma: título e corpo do PR em INGLÊS — convenção deste repo em docs/agents/skills-config.md; estrutura de seções do role file mantida).

- Título sugerido: ${setup.prTitle || ARGS.prTitleHint || '(derive do plano)'}
- Resumo do plano: ${setup.planSummary || '(leia o plano)'}
- Origem do plano (linkar em ## Context): veja o cabeçalho "Origem" do arquivo de plano (issue #119).
- Base do "## Test plan": os testes nomeados por contract item abaixo (marque [x] os que o verify já executou; itens com justificativa na entram como nota, não como checkbox):
${JSON.stringify(testEvidence, null, 2)}
- Decisões tomadas autonomamente (obrigatórias no corpo, uma a uma):
${JSON.stringify(decisions, null, 2)}
- Residuais do verify-plan para a seção "## What this PR does NOT cover" (vazio = omita a seção):
${JSON.stringify(residual, null, 2)}
- ${mustFullBuild ? `Houve fixes pós-verify: re-rode o gate completo antes de abrir o PR (além da regra de rebase do role file):\n${VERIFY_CMDS}` : `Build já verificado; re-rode o gate completo apenas se o rebase trouxer mudanças de ${BASE} (regra do role file). Gate:\n${VERIFY_CMDS}`}
- Se ARGS.prBase estiver definido (${ARGS.prBase || '(não definido — use ' + BASE + ')'}), abra o PR com --base nessa branch (stack de PRs empilhados), senão --base ${BASE}. O rebase pré-PR é sobre a base do PR, não necessariamente ${BASE}.`
}

// ---------------------------------------------------------------------------
// Fases
// ---------------------------------------------------------------------------

phase('Setup')
const setup = await agent(setupPrompt(), { schema: SETUP_RESULT, label: 'setup', model: MODELS.setup })
if (!setup) return { status: 'blocked', stage: 'setup', reason: 'agente de setup morreu sem resultado' }
if (!setup.branchOk) return { status: 'blocked', stage: 'setup', reason: setup.blockedReason || 'branch/preflight inválido' }

const waves = (setup.waves || []).slice(0, MAX_WAVES)
log(`${setup.resumed ? 'RETOMADA — ' : ''}${waves.length} onda(s) pendente(s): ${waves.map((w) => `${w.id}:${w.title}`).join(' · ')}`)
if (!waves.length && !setup.resumed) return { status: 'blocked', stage: 'setup', reason: 'setup não produziu ondas' }

phase('Implement')
const allDecisions = []
const allTestEvidence = []
const waveReports = []
let blocked = null
// gate de fechamento: done com untestedItems não-vazio NÃO fecha a onda
const closeFailure = (r) => {
  if (!r) return 'sem resultado'
  if (r.status !== 'done') return r.blockedReason || 'blocked sem motivo'
  if ((r.untestedItems || []).length) return `gate de testes: itens sem teste nem justificativa — ${r.untestedItems.join(' | ')}. Escreva os testes (ou justifique na em testEvidence) para fechar a onda.`
  return null
}
for (const wave of waves) {
  let res = await agent(wavePrompt(wave), { schema: WAVE_RESULT, label: `wave-${wave.id}: ${wave.title}`, phase: 'Implement', model: MODELS.wave })
  let failure = closeFailure(res)
  if (failure) {
    log(`onda ${wave.id} não fechou (${failure.slice(0, 160)}) — retry único com agente-julgador (${MODELS.waveRetry})`)
    res = await agent(wavePrompt(wave, failure), { schema: WAVE_RESULT, label: `wave-${wave.id}-retry`, phase: 'Implement', model: MODELS.waveRetry })
    failure = closeFailure(res)
  }
  if (failure) {
    blocked = { wave: wave.id, title: wave.title, reason: failure }
    break
  }
  allDecisions.push(...(res.decisions || []))
  allTestEvidence.push(...(res.testEvidence || []))
  waveReports.push({ wave: wave.id, title: wave.title, commits: res.commitShas || [], handoff: res.handoff || 'none' })
  log(`onda ${wave.id} concluída: ${(res.commitShas || []).length} commit(s), ${(res.decisions || []).length} decisão(ões), ${(res.testEvidence || []).length} item(ns) com teste nomeado`)
}
if (blocked) {
  return { status: 'blocked', stage: 'implement', blocked, wavesDone: waveReports, decisions: allDecisions, note: 'trabalho das ondas concluídas está commitado e pushado na branch' }
}

phase('Verify')
let green = false
let failingSummary = ''
for (let attempt = 1; attempt <= 3 && !green; attempt++) {
  const v = await agent(verifyPrompt(attempt, failingSummary), { schema: VERIFY_RESULT, label: `verify-${attempt}`, phase: 'Verify', model: MODELS.verify })
  green = !!v?.green
  failingSummary = v?.failingSummary || ''
  if (!green) log(`verify tentativa ${attempt}: ainda vermelho — ${failingSummary.slice(0, 200)}`)
}
if (!green) {
  return { status: 'verify-failed', stage: 'verify', failingSummary, wavesDone: waveReports, decisions: allDecisions, note: 'branch pushada com build vermelho — NÃO abrir PR' }
}

let recon = await agent(reconPrompt(false), { schema: RECON_RESULT, label: 'verify-plan', phase: 'Verify', model: MODELS.recon })
let reconFixed = false
if (recon && ((recon.missing || []).length || (recon.diverged || []).length || (recon.untestedPremises || []).length)) {
  log(`verify-plan: ${(recon.missing || []).length} missing, ${(recon.diverged || []).length} diverged, ${(recon.untestedPremises || []).length} premissa(s) sem teste — 1 rodada de fix`)
  const fix = await agent(reconFixPrompt(recon), { schema: WAVE_RESULT, label: 'recon-fix', phase: 'Verify', model: MODELS.reconFix })
  if (fix?.decisions) allDecisions.push(...fix.decisions)
  reconFixed = true
  recon = await agent(reconPrompt(true), { schema: RECON_RESULT, label: 'verify-plan-recheck', phase: 'Verify', model: MODELS.recon })
}
const residual = recon || { missing: [], diverged: [], unplanned: [] }

phase('PR')
const pr = await agent(prPrompt(setup, allDecisions, residual, reconFixed, allTestEvidence), { schema: PR_RESULT, label: 'pr-author', phase: 'PR', model: MODELS.pr })
return {
  status: pr?.status || 'blocked',
  stage: 'pr',
  prNumber: pr?.prNumber,
  prUrl: pr?.prUrl,
  rebased: pr?.rebased || false,
  blockedReason: pr?.blockedReason,
  resumed: setup.resumed,
  wavesDone: waveReports,
  decisions: allDecisions,
  testEvidence: allTestEvidence,
  verifyPlanResiduals: residual,
  models: MODELS,
}

