export const meta = {
  name: 'review-fix-loop',
  description: 'Loop review→conciliate→fix sobre um PR aberto até exaustão (0 High/Blocker em round de largura + enumeração seca), com cap de rounds + rodada final de Medium/Low; posta cada review consolidado no PR',
  whenToUse: 'Invocado pela skill /review-fix-loop (~/.claude/skills/review-fix-loop/SKILL.md) com um PR aberto e a branch dele checked out.',
  phases: [
    { title: 'Classify', detail: 'standard (espelho da action da Anthropic) vs deep (8 lentes do deep-review)' },
    { title: 'Review', detail: 'round 1/gate: fan-out de largura (8 lentes); rounds 2+: validador bounded dos fixes + reviewer do fix-diff' },
    { title: 'Enumerate', detail: 'exaure cada superfície quente (facetas com evidência) no mesmo round' },
    { title: 'Conciliate', detail: 'funde com comentários/reviews já postados, dedupa, posta no PR' },
    { title: 'Fix', detail: 'endereça Blocker/High + Mediums envelhecidos, commit+push, atualiza descrição, responde divergências' },
  ],
}

// args chega como string JSON-encoded em alguns runtimes — shim defensivo.
const ARGS = (() => {
  try { return typeof args === 'string' ? JSON.parse(args) : (args ?? {}) } catch (e) { return {} }
})()

const REQUIRED = ['prNumber', 'repoRoot', 'branch']
const missingArgs = REQUIRED.filter((k) => !ARGS[k])
if (missingArgs.length) {
  return { status: 'blocked', stage: 'args', reason: `args obrigatórios ausentes: ${missingArgs.join(', ')}` }
}

const PR = ARGS.prNumber
const MAX_ROUNDS = Math.min(Math.max(ARGS.maxRounds || 5, 1), 10)
const MAX_EXTENSIONS = Math.min(Math.max(ARGS.maxExtensions ?? 2, 0), 5)
const MAX_ENUM_SURFACES = Math.min(Math.max(ARGS.maxEnumSurfaces ?? 6, 1), 12)
const ROLE_DIR = '/Users/rodrigooliveira/.claude/skills/review-fix-loop/agents'
// Optional per-run model override for every agent (e.g. "opus"); undefined = inherit session model.
const MODEL = ARGS.model || undefined
const DEEP_DIR = `${ARGS.repoRoot}/.claude/skills/deep-review/agents`
const DEEP_AGENTS = [
  { key: 'financial', file: '01-financial-flows.md' },
  { key: 'adjacent', file: '02-adjacent-code.md' },
  { key: 'pipeline', file: '03-payment-pipeline.md' },
  { key: 'dsa', file: '04-dsa-lifecycle.md' },
  { key: 'tests', file: '05-test-coverage.md' },
  { key: 'quantity', file: '06-derived-quantity.md' },
  { key: 'negspace', file: '07-negative-space.md' },
  { key: 'contract', file: '08-contract-reconciler.md' },
]

// ---------------------------------------------------------------------------
// Schemas
// ---------------------------------------------------------------------------

const SEVERITIES = ['Blocker', 'High', 'Medium', 'Low']

const FINDING = {
  type: 'object',
  required: ['id', 'severity', 'title', 'description'],
  properties: {
    id: { type: 'string', maxLength: 60, description: 'slug estável derivado de arquivo+tema, ex.: payout-sweep-cap' },
    severity: { type: 'string', enum: SEVERITIES },
    title: { type: 'string', maxLength: 120 },
    file: { type: 'string', maxLength: 160 },
    line: { type: 'string', maxLength: 20 },
    surface: { type: 'string', maxLength: 80, description: 'slug arquivo+mecanismo (ex.: StoreStopLossService.paidOrig-query) — agrupa Blocker/High para a enumeração de facetas; mesma raiz = mesma chave' },
    description: { type: 'string', maxLength: 500, description: 'cenário concreto em que algo observável dá errado' },

