function ctx() {
  return [
    `PR alvo: #${PR} no repo em ${ARGS.repoRoot} (origin). Branch do PR: ${ARGS.branch} — já checked out na working tree.`,
    `Trabalhe SOMENTE dentro do repo; use rg, nunca grep -r; não leia /tmp, ~, nem worktrees irmãs.`,
    `Antes de qualquer coisa: git branch --show-current deve retornar ${ARGS.branch} e git pull --ff-only deve estar no head do PR. Divergiu → retorne blocked.`,
    `Seu texto final é parseado como dado estruturado — siga o schema, sem prosa extra.`,
    ...(ARGS.directives ? [`DIRETIVAS DO ORQUESTRADOR/USUÁRIO (precedência sobre qualquer julgamento autônomo):\n${ARGS.directives}`] : []),
  ].join('\n')
}

function classifyPrompt() {
  return `${ctx()}

Você decide a profundidade do review deste PR. Colete: gh pr view ${PR} --json title,body,additions,deletions,files; domínios tocados (git diff --name-only origin/main...HEAD).

Escolha "deep" se QUALQUER um:
- Existe contrato deep-plan commitado nesta branch (.claude/deep-plan/*.md no diff)${ARGS.deepPlanContractOnBranch ? ' — JÁ CONFIRMADO pelo orquestrador: há contrato na branch' : ''};
- O diff toca domínio money (paymentgateway, storecredit, billing, debtsettlement, cohort, payout, notary) E muda status/lifecycle, state machine, fluxo de settlement/payout, cálculo monetário ou migration com backfill;
- A mudança é grande/delicada a ponto de um reviewer único provavelmente perder interações emergentes (régua: >~25 arquivos de produção, ou concorrência/async ordering novos).

Senão "standard". Hints do orquestrador: moneyDomains=${JSON.stringify(ARGS.moneyDomains || [])}, diffFiles=${ARGS.diffFiles ?? 'desconhecido'}.`
}

function contractNote() {
  const confirmed = ARGS.deepPlanContractOnBranch ? ' (o orquestrador CONFIRMOU que há contrato nesta branch)' : ''
  return `Plan-contract como input${confirmed}: se a branch tem contrato commitado (.claude/deep-plan/*.md — confira com git diff --name-only origin/main...HEAD), LEIA-O antes de analisar o diff. Fixers de rounds anteriores atualizam nele a semântica que mintaram (dimension rows, premissas, itens riscados) — o contrato é a spec ATUAL, não a do plano original. Divergência código↔contrato é finding; quantia monetária derivada presente no código sem dimension row/premissa correspondente no contrato também é finding (High).`
}

function standardReviewPrompt(round) {
  return `${ctx()}

Leia ${ROLE_DIR}/standard-review.md e opere como esse reviewer (round ${round}). Você revisa o head ATUAL do PR — rounds anteriores podem já ter consertado coisas; reporte o que está no código agora, não o histórico.

${contractNote()}`
}

function deepReviewPrompt(a, round, kind) {
  return `${ctx()}

Leia ${DEEP_DIR}/${a.file} e opere como esse especialista (round ${round} do review-fix-loop${kind === 'gate' ? ' — GATE de exaustão: rounds anteriores zeraram High/Blocker em passes dirigidos; você é o olhar limpo de largura que confirma ou refuta a exaustão' : ''}). Se o role file não existir nesta branch, retorne imediatamente {"findings": []}.

Contexto que você mesmo coleta (Phase 1 do deep-review): diff via gh pr diff ${PR}; metadados via gh pr view ${PR} --json title,body,files; docs/CORE_TENETS.md; docs/schema/{domínio}.md e docs/{domínio}/premises.md dos domínios afetados; CLAUDE.md. NÃO leia comentários/reviews existentes do PR — olhar limpo. O diff é a fonte de verdade do que está sendo proposto; leia os arquivos completos para contexto adjacente. Verifique antes de reportar (grep/leia antes de afirmar "X não trata Y").

${contractNote()}

Converta seus achados para o schema de findings (severidades Blocker/High/Medium/Low conforme seu role file; impacto financeiro é sempre Blocker). Para cada Blocker/High preencha "surface" (slug arquivo+mecanismo).`
}

function consolidatePrompt(slices, round) {
  return `${ctx()}

Leia ${DEEP_DIR}/99-consolidate.md e aplique a lógica de consolidação (dedup, verificação dos high-severity — demoção de B/H só com evidência lida no código, classificação) aos findings dos ${slices.length} especialistas abaixo (round ${round}). NÃO poste nada no GitHub — devolva apenas a lista consolidada no schema. Para cada Blocker/High preencha "surface" (slug arquivo+mecanismo; mesma raiz = mesma chave) — é a chave do estágio de enumeração.

Findings dos especialistas:
${JSON.stringify(slices, null, 2)}`
}

function enumeratePrompt(surface, seeds, round, opts) {
  return `${ctx()}

Leia ${DEEP_DIR}/95-enumerate.md e opere como esse enumerador de facetas (round ${round} do review-fix-loop). Se o role file não existir nesta branch, retorne imediatamente {"surface": ${JSON.stringify(surface)}, "dry": true, "facets": [], "findings": []}.

Superfície quente: ${surface}

Findings-semente (Blocker/High confirmados nesta superfície):
${JSON.stringify(seeds, null, 2)}

${opts.postFix
    ? `Os findings-semente acabaram de ser endereçados pelo fixer (commits: ${JSON.stringify(opts.commits || [])}). NÃO re-reporte o defeito-semente: audite o código ATUAL da superfície — as facetas irmãs que o fix não cobriu e regressões que o próprio fix introduziu nela.`
    : `Os findings-semente ainda NÃO foram corrigidos. NÃO os re-reporte — procure as facetas irmãs da mesma superfície.`}

${contractNote()}

Para cada finding novo preencha "surface" com a mesma chave acima. "dry": true só com a tabela de facetas toda "ok" com evidência — nunca marque ok sem file:line.`
}

function validationPrompt(claimedFixed, fixResult, postCap) {
  return `${ctx()}

Você é o VALIDADOR bounded do review-fix-loop${postCap ? ' (pós-cap: o loop atingiu o cap de rounds logo depois deste fix — não houve review de validação)' : ''}. O fixer do round anterior alegou ter consertado os findings abaixo. Seu escopo é FECHADO: para CADA finding abaixo, julgue adversarialmente se o fix presente no head atual resolve o cenário concreto do finding — leia o código pós-fix (file:line), rode um teste direcionado se houver um óbvio. NÃO procure problemas novos, NÃO re-revise o PR, NÃO edite nada.

Findings consertados sem validação (com a nota do fixer em fixNote):
${JSON.stringify(claimedFixed, null, 2)}

Commits do fixer: ${JSON.stringify(fixResult?.commits || [])}

Todo finding abaixo deve aparecer em exatamente um dos buckets: resolved (com evidence file:line) ou stillOpen (com why concreto).`
}

function fixDiffPrompt(commits, round) {
  return `${ctx()}

Você é o reviewer de FIX-DIFF (round ${round} do review-fix-loop). O fixer do round anterior pushou os commits: ${JSON.stringify(commits)}.

Revise SOMENTE o código tocado por esses commits (git show <sha>, git diff <primeiro>^..<último>) — você procura o que os próprios fixes introduziram: regressão, predicado/janela temporal/fórmula com semântica nova, quantia monetária derivada mintada sem dimension row no contrato, guard copiado cuja precondição não vale para o novo caller, teste enfraquecido para passar. NÃO re-revise o PR inteiro — só o delta dos fixes. Verifique antes de reportar.

${contractNote()}

Severidades padrão (impacto financeiro = Blocker). Para cada Blocker/High preencha "surface" (slug arquivo+mecanismo).`
}

function conciliatePrompt(freshFindings, state, round, mode, kind, mediumAges) {
  return `${ctx()}

Leia ${ROLE_DIR}/conciliate.md e opere como esse agente (round ${round}, modo ${mode}, tipo de round: ${kind}).

Findings frescos desta rodada (o campo source distingue: especialistas/consolidador, validador pós-fix, fix-diff, enumerate:<surface>):
${JSON.stringify(freshFindings, null, 2)}

Estado do loop (rounds anteriores):
- fixed: ${JSON.stringify(state.fixed)}
- diverged (contestados pelo fixer, argumento postado no PR): ${JSON.stringify(state.diverged)}
- idade dos Mediums (rounds consecutivos em que o id apareceu — ≥2 indica fila estagnada; re-precifique ou marque a idade): ${JSON.stringify(mediumAges)}`
}

function fixerPrompt(findings, round, opts) {
  const aged = (opts.agedMediums || []).map((m) => m.id)
  return `${ctx()}

Leia ${ROLE_DIR}/fixer.md e opere como esse agente (round ${round}).

${opts.finalRound
    ? `RODADA FINAL: o review zerou High/Blocker. Enderece os Medium/Low pendentes abaixo. Depois de você NINGUÉM revisa de novo — rode o /verify COMPLETO (incluindo ./gradlew clean build) antes do push final.`
    : `Enderece os Blocker/High abaixo${aged.length ? ` e os Mediums ENVELHECIDOS (≥2 rounds na fila — atribuídos, não opcionais: fix ou divergência formal): ${JSON.stringify(aged)}` : ''}. Mediums oportunísticos (mesmos arquivos): ${JSON.stringify(opts.mediumsInSameFiles || [])}${opts.mustFullVerify ? '\n\nÚLTIMO ROUND POSSÍVEL (cap do loop): depois de você nenhum review valida e nenhum fixer corrige — rode o /verify COMPLETO (incluindo ./gradlew clean build) antes do push, exatamente como numa rodada final.' : ''}`}

Findings atribuídos:
${JSON.stringify(findings, null, 2)}`
}

function cappedCommentPrompt(buckets, roundsSummary, gatePending) {
  return `${ctx()}

O review-fix-loop atingiu o cap de rounds. Poste um comentário no PR (gh pr comment ${PR} --body-file <tmpfile>) em pt-br, marcador <!-- review-fix-loop: capped -->, com os buckets abaixo em seções SEPARADAS — a distinção entre eles é o que torna o comentário verdadeiro (o último review e o último fix são instantes diferentes; não os misture):

1. "Abertos" — High/Blocker sem fix, ou cujo fix o validador julgou insuficiente (campo validatorNote):
${JSON.stringify(buckets.open, null, 2)}

2. "Consertados no último round — validação bounded OK, sem review completo" (campo evidence):
${JSON.stringify(buckets.fixedValidated, null, 2)}

3. "Consertados no último round — SEM validação" (alegação do fixer apenas):
${JSON.stringify(buckets.fixedUnreviewed, null, 2)}

4. "Contestados pelo fixer, sem re-avaliação" (argumento já postado no PR):
${JSON.stringify(buckets.contested, null, 2)}

${gatePending ? 'ATENÇÃO: o último round zerou High/Blocker em passe DIRIGIDO (depth), mas o gate fresh-eyes de largura NÃO chegou a rodar — o loop capou antes. Diga explicitamente que a exaustão NÃO foi confirmada e recomende rodar /deep-review ou um novo loop como gate.' : ''}

Omita seções vazias. Inclua a trajetória de severidades por round (com o tipo de cada round — breadth/depth/gate — e se a enumeração veio seca) e que o loop parou aguardando decisão humana. Telegráfico e honesto — sem maquiar.

Trajetória:
${JSON.stringify(roundsSummary, null, 2)}

Retorne apenas { "findings": [] } vazio no schema (o comentário é o efeito).`
}

// ---------------------------------------------------------------------------
// Enumeração de superfícies quentes
// ---------------------------------------------------------------------------

function hotSurfaces(findings) {
  const hb = findings.filter((f) => f.severity === 'Blocker' || f.severity === 'High')
  const bySurface = new Map()
  for (const f of hb) {
    const key = String(f.surface || f.file || f.id || 'unknown').slice(0, 80)
    if (!bySurface.has(key)) bySurface.set(key, [])
    bySurface.get(key).push(f)
  }
  const entries = [...bySurface.entries()]
  entries.sort((a, b) => {
    const aB = a[1].some((f) => f.severity === 'Blocker') ? 0 : 1
    const bB = b[1].some((f) => f.severity === 'Blocker') ? 0 : 1
    return aB - bB
  })
  return { targets: entries.slice(0, MAX_ENUM_SURFACES), truncated: entries.length > MAX_ENUM_SURFACES }
}

async function enumerateSurfaces(seedFindings, round, opts) {
  const { targets, truncated } = hotSurfaces(seedFindings)
  if (!targets.length) return { findings: [], dry: true, surfaces: [], unchecked: 0, truncated: false }
  if (truncated) log(`enumeração r${round}: ${targets.length} superfícies (cap ${MAX_ENUM_SURFACES}) — excedente NÃO enumerado nesta rodada`)
  const results = await parallel(targets.map(([surface, seeds]) => () =>
    agent(enumeratePrompt(surface, seeds, round, opts), { schema: ENUM_RESULT, label: `enum:${surface.slice(0, 40)} r${round}`, phase: 'Enumerate', model: MODEL })
  ))
  const valid = results.filter(Boolean)
  const findings = valid.flatMap((r) => (r.findings || []).map((f) => ({ ...f, surface: f.surface || r.surface, source: f.source || `enumerate:${r.surface}` })))
  const unchecked = valid.reduce((n, r) => n + (r.facets || []).filter((x) => x.verdict === 'unchecked').length, 0)
  // seca = todo enumerador respondeu, nenhum finding novo, nenhuma faceta sem evidência, nenhuma superfície fora do cap
  const dry = valid.length === targets.length && findings.length === 0 && unchecked === 0 && !truncated
  log(`enumeração r${round}: ${targets.length} superfícies → ${findings.length} finding(s) novo(s), ${unchecked} faceta(s) unchecked${dry ? ' — SECA' : ''}`)
  return { findings, dry, surfaces: targets.map(([s]) => s), unchecked, truncated }
}

// ---------------------------------------------------------------------------
// Fases
// ---------------------------------------------------------------------------

phase('Classify')
let mode = ARGS.modeHint === 'deep' || ARGS.modeHint === 'standard' ? ARGS.modeHint : null
if (mode) {
  log(`modo forçado pelo usuário: ${mode}`)
} else {
  const c = await agent(classifyPrompt(), { schema: CLASSIFY_RESULT, label: 'classify', model: MODEL })
  mode = c?.mode === 'deep' ? 'deep' : 'standard'
  log(`modo: ${mode} — ${c?.reason || 'classificador morreu; fallback standard'}`)
}

const state = { fixed: [], diverged: [] }
const roundsSummary = []
const allCommits = []
const seenIds = new Set()
const mediumAge = new Map()
let effectiveMax = MAX_ROUNDS
let extensionsUsed = 0
let gateExtensionUsed = 0
let pendingGate = false
let lastHighBlocker = []
let lastFixResult = null
let finalStatus = 'capped'
let blockedReason = null

for (let round = 1; round <= effectiveMax; round++) {
  let freshFindings = []
  let enumInfo = { findings: [], dry: true, surfaces: [], unchecked: 0, truncated: false }
  let roundKind

  if (mode === 'standard') {
    // --- Standard: 1 reviewer de largura por round (PRs simples; sem enumeração) ---
    roundKind = 'standard'
    const r = await agent(standardReviewPrompt(round), { schema: FINDINGS, label: `review r${round}`, phase: 'Review', model: MODEL })
    freshFindings = r?.findings ?? []
  } else if (round === 1 || pendingGate) {
    // --- Largura (round 1 ou gate fresh-eyes): fan-out das 8 lentes + consolidação + enumeração ---
    roundKind = pendingGate ? 'gate' : 'breadth'
    pendingGate = false
    const slices = await parallel(DEEP_AGENTS.map((a) => () =>
      agent(deepReviewPrompt(a, round, roundKind), { schema: FINDINGS, label: `deep:${a.key} r${round}`, phase: 'Review', model: MODEL })
    ))
    const valid = slices.filter(Boolean)
    const cons = await agent(consolidatePrompt(valid, round), { schema: FINDINGS, label: `consolidate r${round}`, phase: 'Review', model: MODEL })
    const consolidated = cons?.findings ?? valid.flatMap((s) => s.findings || [])
    enumInfo = await enumerateSurfaces(consolidated, round, { postFix: false })
    freshFindings = consolidated.concat(enumInfo.findings)
  } else {
    // --- Profundidade (rounds 2+): validador bounded + fix-diff + re-enumeração das superfícies recém-fixadas.
    // Regressão de fix é rara e local (PR #1065: 2/28, ambas pegas no round em que nasceram) — re-varredura
    // plena a cada round paga por cobertura que já existe; a largura volta só no gate de exaustão. ---
    roundKind = 'depth'

    // 1. Valida as alegações de fix do round anterior (escopo fechado nos ids)
    let stillOpen = []
    const fixedById = new Map((lastFixResult?.fixed || []).map((f) => [f.id, f.note || '']))
    const claims = lastHighBlocker.filter((f) => fixedById.has(f.id)).map((f) => ({ ...f, fixNote: fixedById.get(f.id) }))
    if (claims.length) {
      const val = await agent(validationPrompt(claims, lastFixResult, false), { schema: VALIDATION_RESULT, label: `validate r${round}`, phase: 'Review', model: MODEL })
      if (val) {
        const stillById = new Map((val.stillOpen || []).map((s) => [s.id, s.why]))
        stillOpen = claims.filter((c) => stillById.has(c.id)).map((c) => ({ ...c, description: `${String(c.description).slice(0, 280)} [validador: ${stillById.get(c.id)}]`.slice(0, 500), source: 'validador pós-fix' }))
      } else {
        // validador morreu — re-entra tudo por segurança; o conciliador verifica B/H no código antes de postar
        stillOpen = claims.map((c) => ({ ...c, source: 'validador morreu — re-entra por segurança' }))
      }
    }

    // 2. Review do fix-diff: só o delta dos commits do fixer (pega fix-introduced no round seguinte)
    let fdFindings = []
    const commits = lastFixResult?.commits || []
    if (commits.length) {
      const fd = await agent(fixDiffPrompt(commits, round), { schema: FINDINGS, label: `fixdiff r${round}`, phase: 'Review', model: MODEL })
      fdFindings = (fd?.findings ?? []).map((f) => ({ ...f, source: f.source || 'fix-diff' }))
    }

    // 3. Re-enumera as superfícies dos B/H do round anterior (o fixer acabou de mexer nelas — padrão paidOrig)
    enumInfo = await enumerateSurfaces(lastHighBlocker, round, { postFix: true, commits })

    freshFindings = stillOpen.concat(fdFindings, enumInfo.findings)
  }

  // --- Conciliate (única etapa que lê o histórico do PR; posta o consolidado) ---
  const con = await agent(
    conciliatePrompt(freshFindings, state, round, mode, roundKind, Object.fromEntries(mediumAge)),
    { schema: CONSOLIDATED, label: `conciliate r${round}`, phase: 'Conciliate', model: MODEL }
  )
  const findings = con?.findings ?? freshFindings
  const highBlocker = findings.filter((f) => f.severity === 'Blocker' || f.severity === 'High')
  const mediumLow = findings.filter((f) => f.severity === 'Medium' || f.severity === 'Low')

  // --- Envelhecimento de Mediums: ≥2 rounds na fila → deixam de ser opcionais para o fixer ---
  findings.filter((f) => f.severity === 'Medium').forEach((f) => mediumAge.set(f.id, (mediumAge.get(f.id) || 0) + 1))
  const agedMediums = findings.filter((f) => f.severity === 'Medium' && (mediumAge.get(f.id) || 0) >= 2)

  roundsSummary.push({
    round,
    kind: roundKind,
    blocker: findings.filter((f) => f.severity === 'Blocker').length,
    high: findings.filter((f) => f.severity === 'High').length,
    medium: findings.filter((f) => f.severity === 'Medium').length,
    low: findings.filter((f) => f.severity === 'Low').length,
    enumDry: enumInfo.dry,
    enumSurfaces: enumInfo.surfaces.length,
    agedMediums: agedMediums.length,
    commentUrl: con?.commentUrl,
  })
  log(`round ${round} (${roundKind}): ${highBlocker.length} High/Blocker · ${mediumLow.length} Medium/Low · enum ${enumInfo.dry ? 'seca' : 'NÃO seca'} — ${con?.commentUrl || 'comentário não confirmado'}`)

  // --- Cap dinâmico: Blocker com id inédito no round-cap = regressão introduzida por fix; parar agora é pior ---
  const newBlockers = findings.filter((f) => f.severity === 'Blocker' && !seenIds.has(f.id))
  findings.forEach((f) => seenIds.add(f.id))
  if (round === effectiveMax && highBlocker.length > 0 && newBlockers.length > 0 && extensionsUsed < MAX_EXTENSIONS) {
    effectiveMax++
    extensionsUsed++
    log(`round ${round} (cap) achou Blocker(s) inédito(s): ${newBlockers.map((b) => b.id).join(', ')} — cap estendido para ${effectiveMax} (extensão ${extensionsUsed}/${MAX_EXTENSIONS}); re-disputa de id já visto não estende`)
  }

  lastHighBlocker = highBlocker

  // --- Terminação por exaustão: 0 High/Blocker num round de LARGURA com enumeração seca.
  // Um round depth com 0 H/B só agenda o gate fresh-eyes — quiet não é exausto. ---
  if (highBlocker.length === 0) {
    const exhausted = mode === 'standard' || (roundKind !== 'depth' && enumInfo.dry)
    if (exhausted) {
      if (mediumLow.length) {
        const fin = await agent(fixerPrompt(mediumLow, round, { finalRound: true }), { schema: FIX_RESULT, label: 'final-fix (medium/low)', phase: 'Fix', model: MODEL })
        if (fin?.status === 'done') {
          state.fixed.push(...(fin.fixed || []))
          state.diverged.push(...(fin.diverged || []))
          allCommits.push(...(fin.commits || []))
        } else {
          log(`rodada final de Medium/Low travou: ${fin?.blockedReason || 'sem resultado'} — pendências documentadas no PR`)
        }
      }
      finalStatus = 'clean'
      break
    }
    pendingGate = true
    if (round === effectiveMax && gateExtensionUsed < 1) {
      effectiveMax++
      gateExtensionUsed++
      log(`round ${round} (${roundKind}) zerou High/Blocker mas exaustão não confirmada — cap estendido em +1 para o gate fresh-eyes`)
    } else if (round === effectiveMax) {
      log(`round ${round} zerou High/Blocker mas o gate fresh-eyes não cabe no cap — loop termina capped com 0 abertos e exaustão NÃO confirmada`)
    } else {
      log(`round ${round} (${roundKind}) zerou High/Blocker — próximo round é o gate fresh-eyes de largura`)
    }
    continue
  }

  // --- Fix Blocker/High + Mediums envelhecidos (no último round possível: verify completo) ---
  const assigned = highBlocker.concat(agedMediums.filter((m) => !highBlocker.some((h) => h.id === m.id)))
  const fix = await agent(
    fixerPrompt(assigned, round, {
      finalRound: false,
      mustFullVerify: round === effectiveMax,
      agedMediums,
      mediumsInSameFiles: mediumLow.filter((m) => !agedMediums.some((a) => a.id === m.id) && highBlocker.some((h) => h.file && h.file === m.file)),
    }),
    { schema: FIX_RESULT, label: `fix r${round}`, phase: 'Fix', model: MODEL }
  )
  if (!fix || fix.status === 'blocked') {
    finalStatus = 'blocked'
    blockedReason = fix?.blockedReason || 'fixer morreu sem resultado'
    break
  }
  lastFixResult = fix
  state.fixed.push(...(fix.fixed || []))
  state.diverged.push(...(fix.diverged || []))
  allCommits.push(...(fix.commits || []))
  // Mediums consertados saem da fila de envelhecimento
  ;(fix.fixed || []).forEach((f) => mediumAge.delete(f.id))
  log(`round ${round} fix: ${(fix.fixed || []).length} consertado(s), ${(fix.diverged || []).length} divergência(s), ${(fix.commits || []).length} commit(s)`)
}

// --- Reconciliação pós-cap: o último review (pré-fix) e o último fix são instantes diferentes.
// openHighBlocker cru do round-cap reportaria como aberto o que o fixer acabou de endereçar (bug do run #1065).
let openHighBlocker = finalStatus === 'clean' ? [] : lastHighBlocker
let fixedValidated = []
let fixedUnreviewed = []
let contestedUnreviewed = []
if (finalStatus === 'capped') {
  const lastFixedById = new Map((lastFixResult?.fixed || []).map((f) => [f.id, f.note || '']))
  const lastDivergedIds = new Set((lastFixResult?.diverged || []).map((d) => d.id))
  contestedUnreviewed = lastHighBlocker.filter((f) => lastDivergedIds.has(f.id))
  const claimedFixed = lastHighBlocker
    .filter((f) => lastFixedById.has(f.id))
    .map((f) => ({ ...f, fixNote: lastFixedById.get(f.id) }))
  openHighBlocker = lastHighBlocker.filter((f) => !lastFixedById.has(f.id) && !lastDivergedIds.has(f.id))

  if (claimedFixed.length) {
    // "fixed" é alegação do fixer — validação bounded (1 agente, escopo fechado nos ids), não um review novo.
    const val = await agent(validationPrompt(claimedFixed, lastFixResult, true), { schema: VALIDATION_RESULT, label: 'fix-validation pós-cap', phase: 'Fix', model: MODEL })
    if (val) {
      const resolvedById = new Map((val.resolved || []).map((r) => [r.id, r.evidence || '']))
      const stillOpenById = new Map((val.stillOpen || []).map((s) => [s.id, s.why]))
      fixedValidated = claimedFixed.filter((f) => resolvedById.has(f.id)).map((f) => ({ ...f, evidence: resolvedById.get(f.id) }))
      openHighBlocker = openHighBlocker.concat(
        claimedFixed.filter((f) => stillOpenById.has(f.id)).map((f) => ({ ...f, validatorNote: stillOpenById.get(f.id) }))
      )
      fixedUnreviewed = claimedFixed.filter((f) => !resolvedById.has(f.id) && !stillOpenById.has(f.id))
    } else {
      fixedUnreviewed = claimedFixed
    }
  }

  await agent(cappedCommentPrompt({ open: openHighBlocker, fixedValidated, fixedUnreviewed, contested: contestedUnreviewed }, roundsSummary, pendingGate), { schema: FINDINGS, label: 'capped-comment', phase: 'Conciliate', model: MODEL })
}

return {
  status: finalStatus,
  mode,
  rounds: roundsSummary,
  extensionsUsed,
  gateNeverRan: finalStatus === 'capped' && pendingGate,
  commits: allCommits,
  fixed: state.fixed,
  diverged: state.diverged,
  openHighBlocker,
  fixedValidated,
  fixedUnreviewed,
  contestedUnreviewed,
  blockedReason,
}
